// 0.16.1: manifest příkazů aplikace. Jakmile manifest příkazy vyjmenuje, Tauri 2 povolí každý `#[tauri::command]`
// jen oknům, jejichž capability v capabilities/<okno>.json obsahuje jeho `allow-<příkaz>`; bez manifestu by každé
// okno smělo volat všechno. Seznam musí odpovídat generate_handler! v src/lib.rs (hlídá tests/safety-acl.test.ts).
// Oprávnění se generují do permissions/autogenerated (v .gitignore).
const COMMANDS: &[&str] = &[
    "storage_load",
    "storage_save",
    "snapshot_create",
    "snapshot_list",
    "snapshot_read",
    "snapshot_delete",
    "import_save_raw",
    "export_backup",
    "import_backup",
    "data_dir",
    "open_data_dir",
    "open_external",
    "launch_info",
    "bus_send",
    "ops_enable",
    "ops_hotkey",
    "ops_watch",
    "buddy_open",
    "buddy_close",
    "buddy_reveal",
    "overlay_open",
    "overlay_close",
    "overlay_toggle",
    "main_focus",
    "capture_now",
    "capture_take",
    "ops_autocapture",
    "ops_autostats",
    "win_place",
    "win_drag",
    "widgets_open",
    "widgets_close",
    "widgets_edit",
    "widgets_fit",
    "widgets_app",
    "main_mode",
    "main_pin",
    "main_geometry",
    "main_drag",
    "main_minimize",
    "main_hide",
    "main_show",
    "main_ready",
    "app_quit",
    "tray_sync",
];

fn main() {
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)))
        .expect("tauri-build selhal");
}
